export const BODY: string = "\n<p>التباين هو الفرق بين أظلم أجزاء الصورة وأفتحها: إنه ما يجعل صورة تشعر بالقوة والصلابة، أو مسطحة ورمادية.</p>\n<p>صورة بتباين جيد لها ظلال عميقة وإضاءات ساطعة وإحساس واضح بالعمق: وصورة بتباين قليل تبدو ضبابية، كأنها التُقطت من خلال ضباب.</p>\n<p>يشرح هذا الدليل كيف يعمل التباين وكيف تستخدم المنزلق والإعدادات السريعة جيدًا وكيف تضيف قوة دون قص الإضاءات أو سحق الظلال: يغطي صورًا شخصية ومناظر ولقطات شاشة وأخطاء تفسد تعديلًا جيدًا.</p>\n<h2 id=\"what-contrast-does\">ماذا يفعل التباين فعلًا؟</h2>\n<p>التباين يمد أو يضغط النطاق النغمي لصورة: عند رفعه، تصبح البكسلات الداكنة أظلم والفاتحة أفتح، موسعة الفجوة بينهما.</p>\n<p>خفض التباين يفعل العكس: يقرب الداكن والفاتح، ملطفًا الصورة ومقللًا الفرق بين ألمع أجزائها وأظلمها. والتباين لا يغيّر السطوع العام كثيرًا: صورة بتباين عالٍ قد تكون داكنة أو فاتحة عمومًا، لكن ظلالها وإضاءاتها ستكون متباعدة جدًا في كل حال.</p>\n<p>فكر في التباين كمسافة بين طرفي حبل: فصل الطرفين يمد نغمات الصورة، بينما تقريبهما يضغطها نحو الوسط.</p>\n<h2 id=\"why-photos-look-flat\">لماذا تبدو الصور مسطحة؟</h2>\n<p>الضباب هو السبب الأكثر شيوعًا لصورة مسطحة: الضباب والغيوم والهواء الرطب يبعثر الضوء، ما يرفع الظلال ويطفئ الإضاءات حتى تبقى الصورة كلها في الوسط.</p>\n<p>الضوء الغائم يسطّح الصور أيضًا: سماء مغطاة تعطي ضوءًا ناعمًا ومتساويًا، بلا ظلال قوية، فالصورة ليس لها نطاق نغمي كبير من البداية. وصور قديمة ممسوحة غالبًا تبدو مسطحة أيضًا: العمر يبهت المطبوعات، والماسحات تقرأ النغمات خطأ، والنتيجة صورة رمادية وضبابية، بلا سود عميقة ولا بيض ساطع.</p>\n<p>وكاميرات الهواتف قد تنتج صورًا مسطحة في ضوء قليل: المستشعر يكافح لالتقاط النطاق كله، وتخرج الصورة مضغوطة في النغمات الوسطى.</p>\n<h2 id=\"slider-explained\">منزلق التباين موضح</h2>\n<p>يمتد منزلق التباين من قيم سالبة إلى موجبة، والصفر يعني لا تغيير: تحريكه يمينًا يزيد التباين، وتحريكه يسارًا يقلله.</p>\n<p>الحركات الصغيرة تحدث فرقًا كبيرًا: تغيير 10 إلى 20 بالمئة غالبًا يكفي لإصلاح صورة مسطحة، والحركات الأكبر تقص الإضاءات وتسحق الظلال بسرعة. وتعرض الأداة صورتك بزيادة 20 بالمئة فور رفعها: نقطة البداية تلك تعطيك فكرة فورية عن شكل زيادة تباين معتدلة.</p>\n<p>اسحب المنزلق ببطء وراقب المعاينة: التحديث المباشر يُظهر بالضبط كيف تستجيب الصورة، فتستطيع التوقف عند النقطة التي تبدو فيها الصورة جيدة.</p>\n<h2 id=\"quick-presets\">إعدادات سريعة لإصلاحات بنقرة واحدة</h2>\n<p>تشمل الأداة إعدادات سريعة تطبق قيم تباين شائعة بنقرة واحدة: طريقة سريعة لتجربة مستويات مختلفة دون سحب المنزلق.</p>\n<p>الإعدادات السريعة نقطة بداية لا إجابة نهائية: انقر واحدًا وراقب المعاينة ثم اضبط بالمنزلق إذا كانت النتيجة قريبة لكنها ليست صحيحة تمامًا. واستخدم الإعدادات السريعة لمقارنة خيارات بسرعة: إعداد 10 بالمئة بجانب إعداد 30 بالمئة يُظهر كم تباين تتحمل الصورة قبل أن تقص.</p>\n<p>ولدفعة صور متشابهة، نفس الإعداد السريع يحافظ على نتائج متسقة: مجموعة مناظر ضبابية، كلها معززة بنفس المقدار، تبدو كسلسلة.</p>\n<h2 id=\"compare-modes\">أوضاع المقارنة: قبل وبعد ومقسم</h2>\n<p>أوضاع المقارنة تُظهر الأصل والنسخة المعدلة معًا: عرض \"بعد\" يُظهر الصورة بتباين أكثر، وعرض \"قبل\" يُظهر الأصل، وعرض \"مقسم\" يُظهر الاثنتين جنبًا إلى جنب.</p>\n<p>المقارنة المقسمة هي الأنفع لعمل التباين: تتيح لك رؤية أي ظلال تعمقت وأي إضاءات فتّحت بالضبط، بخط واضح بين النسختين. والمقارنة بملء الشاشة تعطي أكبر عرض: إنها أفضل طريقة للحكم على تعديل تباين، لأن الصورة بالحجم الكامل تُظهر قصًا قد تخفيه معاينة صغيرة.</p>\n<p>راجع عرض المقارنة قبل كل تنزيل: نظرة سريعة تكشف إضاءات مقصوصة وظلال مسحوقة قد تخفيها معاينة صغيرة.</p>\n<h2 id=\"contrast-and-colour\">التباين واللون: كيف يؤثر كل منهما في الآخر</h2>\n<p>التباين يؤثر في اللون إضافة إلى النغمة: رفع التباين يجعل الألوان أغنى وأكثر تشبعًا، لأن الداكن يصبح أظلم والفاتح أفتح حوله.</p>\n<p>خفض التباين يطفئ الألوان: صورة ناعمة بتباين منخفض لها نغمات رقيقة وباستيل، ما يناسب صورًا شخصية ومناظر حالمة. وذلك الارتباط يعني أن تغيير تباين هو أيضًا تغيير لون: صورة تحتاج قوة أكثر قد تحتاج تباينًا، بينما صورة تحتاج لونًا أكثر قد تحتاج تشبعًا.</p>\n<p>ولعمل اللون تحديدًا، استخدم <a href=\"/ar/taadil-tashabbu-as-sura/\">محرر تشبع الصور</a> بعد تثبيت التباين: الضابطان معًا يمنحانك تحكمًا كاملًا في مظهر الصورة.</p>\n<h2 id=\"contrast-for-portraits\">التباين للصور الشخصية</h2>\n<p>الصور الشخصية تحتاج تباينًا لطيفًا: وجه بتباين كثير جدًا يبدو قاسيًا ومسنًا، بظلال عميقة تحت العينين وبقع فاتحة على الجبهة.</p>\n<p>ابدأ بدفعة صغيرة 10 بالمئة وراجع البشرة: يجب أن يبدو الوجه محددًا، لا كأن الظلال مرسومة. والتباين السالب قد يساعد صورة شخصية قاسية: شمس الظهيرة تخلق ظلالًا قوية على وجه، وانخفاض صغير يلطّفها دون فقدان الشكل العام.</p>\n<p>ولصورة شخصية ملتقطة بضوء نافذة ناعم، التباين غالبًا جيد من البداية: دفعة صغيرة 5 إلى 10 بالمئة تكفي، والحركات الأكبر تضر أكثر مما تنفع.</p>\n<h2 id=\"contrast-for-landscapes\">التباين للمناظر الطبيعية</h2>\n<p>المناظر هي الأكثر استفادة من التباين: مشهد جبلي ضبابي أو وادٍ غائم أو سماء باهتة تكسب عمقًا ودراما بزيادة معتدلة.</p>\n<p>استخدم دفعة 15 إلى 25 بالمئة لمنظر ضبابي: تتعمق الظلال وتفتّح الإضاءات ويكسب المشهد القوة التي سلبها الضباب. وراقب السماء أثناء زيادة التباين: الغيوم تقص أولًا، متحولة إلى بياض فارغ بلا شكل، وسماء مقصوصة تفسد منظرًا جيدًا غير ذلك.</p>\n<p>ولمنظر بسماء صافية ومقدمة داكنة، اقبل تسوية: التباين يمد الطرفين، فالسماء والأرض تتحركان في اتجاهين معاكسين.</p>\n<h2 id=\"contrast-for-screenshots\">التباين للقطات الشاشة والوثائق</h2>\n<p>لقطات الشاشة والوثائق الممسوحة تحتاج تباينًا لتُقرأ: يجب أن يبرز النص عن الخلفية، ومسح بتباين منخفض بنص رمادي صعب القراءة.</p>\n<p>الصق لقطة مباشرة بـCtrl+V لتتخطى خطوة الحفظ: تظهر الصورة في المحرر فورًا، جاهزة للضبط. وزد التباين حتى يصبح النص داكنًا وتصبح الخلفية بيضاء: وثيقة بنص أسود قوي على خلفية بيضاء نظيفة سهلة القراءة والطباعة.</p>\n<p>وراقب الضجيج في الخلفية: مسح بتباين كثير قد يُظهر بقعًا ومصنوعات، خاصة في JPEG مضغوط أصلًا.</p>\n<h2 id=\"negative-contrast\">تباين سالب: كيف تلطّف صورًا قاسية</h2>\n<p>التباين السالب يلطّف صورة بتقريب الداكن والفاتح: إنه الخيار الصحيح لصورة ملتقطة بشمس ظهيرة قاسية.</p>\n<p>استخدم قيمًا مثل 10 أو 20 بالمئة سالبة لتلطيف ظلال قوية في صورة شخصية: الوجه يحافظ على شكله، لكن الحواف القاسية تتلاشى في مظهر أنعم. والتباين السالب يناسب أيضًا مناظر ناعمة وحالمة: مشهد صباحي ضبابي بتباين قليل يشعر بالهدوء والصمت، ما يناسب جو الصورة.</p>\n<p>ولا تبالغ: صورة بتباين قليل جدًا تبدو رمادية وبلا حياة، كأنها التُقطت من خلال ضباب، حتى في يوم صافٍ.</p>\n<h2 id=\"clipping-and-crushing\">كيف تُقص الإضاءات وتُسحق الظلال</h2>\n<p>القص يحدث عندما تُدفع الإضاءات أبعد من الأبيض النقي: تفاصيل غيمة ساطعة أو قميص أبيض تختفي، وتصبح المنطقة فراغًا بلا ملامح.</p>\n<p>والسحق يحدث عندما تُدفع الظلال أبعد من الأسود النقي: تفاصيل معطف داكن أو زاوية في ظل تختفي، وتصبح المنطقة بقعة سوداء صلبة. وكلاهما دائم في الملف المصدر: بمجرد أن يُقص تفصيل أو يُسحق، لا تعديل لاحق يستطيع استعادته، فراجع الطرفين قبل التنزيل.</p>\n<p>استخدم عرض المقارنة لاكتشاف القص والسحق: العرض المقسم يُظهر بالضبط أي مناطق فقدت تفاصيل، وتقليل صغير للمنزلق غالبًا يستعيدها.</p>\n<h2 id=\"formats-and-export\">الصيغ والتصدير</h2>\n<p>تقبل الأداة صيغ صور شائعة، بما فيها JPG وPNG وWebP وHEIC، بملفات حتى 20 MB: وتستطيع التصدير كـJPG أو PNG أو WebP حسب حاجتك.</p>\n<p>التصدير كـPNG أو WebP يحافظ على شفافية الصورة الأساسية: إذا كان مصدرك رسم PNG شفافًا، فالتصدير المعدل بالتباين يحافظ على المناطق الشفافة سليمة. وللصور، JPG بضبط جودة عالية يعمل جيدًا: التباين لا يضيف كثيرًا إلى حجم الملف، فالتصدير يبقى قريبًا من الوزن الأصلي.</p>\n<p>ويظهر ضبط الجودة لتصديرات JPG وWebP، ويُخفى لـPNG، لأن PNG دون فقدان وليس له ضبط جودة لتغييره.</p>\n<h2 id=\"contrast-vs-brightness\">التباين أم السطوع: أيهما أولًا؟</h2>\n<p>السطوع يثبّت المستوى العام، والتباين يثبّت الاتساع حول ذلك المستوى: صورة داكنة جدًا تحتاج سطوعًا أولًا، لأن التباين لا يستطيع إصلاح المستوى.</p>\n<p>صورة مسطحة لكنها مضاءة جيدًا تحتاج تباينًا فقط: تفتيحها سيجعلها أفتح وأكثر تسطحًا، لا أفضل، فتخطَ خطوة السطوع. وعندما تحتاج صورة الاثنين، افعل السطوع أولًا ثم التباين: الترتيب مهم، لأن السطوع يغيّر ما يحتاج تعديل التباين إلى فعله.</p>\n<p>وللمقارنة الكاملة، اقرأ <a href=\"/ar/blog/sutoo-vs-taarid-vs-tabayun/\">السطوع أم التعريض أم التباين: أساسيات التعديل</a>. ولإصلاح صورة داكنة أولًا، استخدم <a href=\"/ar/taadil-sutoo-as-sura/\">محرر سطوع الصور</a>.</p>\n<h2 id=\"privacy-local-processing\">خصوصية: تعديل دون رفع أي شيء</h2>\n<p>كل تعديل تباين يحدث في متصفحك: صورك لا تُرفع أبدًا إلى خادم، وهو أمر مهم عندما تكون الصور شخصية أو صورًا عائلية أو عمل عملاء.</p>\n<p>هذه ميزة حقيقية مقابل محررات السحابة: صورة عائلية أو وثيقة خاصة لا يجب أن تسافر إلى خادم لا تستطيع رؤيته، فقط لإضافة تباين. وتزيل الأداة أيضًا بيانات GPS EXIF عند التصدير: صورة معدلة بالتباين منزلة من الأداة لا تحمل أي سجل لأين التُقطت.</p>\n<p>احتفظ بالصورة الأصلية دون تعديل: بمجرد أن يُسطّح تغيير تباين في تصدير، لا يمكن التراجع عنه من ذلك الملف، فالأصل هو نسختك النظيفة الوحيدة.</p>\n<h2 id=\"common-mistakes\">أخطاء شائعة عند ضبط التباين</h2>\n<p>أكثر خطأ شيوعًا إضافة تباين كثير جدًا: صورة مدفوعة إلى 50 بالمئة أو أكثر تفقد إضاءاتها وظلالها تمامًا، والنتيجة صورة قاسية كملصق.</p>\n<p>خطأ آخر استخدام التباين لإصلاح صورة داكنة: صورة داكنة بتباين عالٍ تبقى داكنة، فقط بظلال أعمق، ويبقى الشخص مخفيًا. وينسى الناس أيضًا مراجعة الطرفين: سماء أو ظل يبدو جيدًا في معاينة صغيرة قد يكون مقصوصًا أو مسحوقًا بالحجم الكامل، فراجع النتيجة دائمًا بحجم كبير.</p>\n<p>وأخيرًا، لا تضبط نفس JPG مرة بعد مرة: كل حفظ يضيف ضررًا، فعد دائمًا إلى الملف الأصلي عندما تريد مستوى تباين مختلفًا.</p>\n<h2 id=\"contrast-workflow\">سير عمل لتعديلات تباين نظيفة</h2>\n<p>ابدأ بالملف الأصلي وقرر إن كانت الصورة مسطحة أو قاسية أو باتساع صحيح: مسطحة تحتاج دفعة، وقاسية تحتاج انخفاضًا، وصحيحة لا تحتاج شيئًا.</p>\n<p>طبّق التباين ثم راجع عرض المقارنة: العرض المقسم يُظهر بالضبط أي ظلال تعمقت وأي إضاءات فتّحت. وراجع الإضاءات والظلال منفصلتين: الإضاءات تقص أولًا بدفعة، والظلال تُسحق أولًا بنفس الحركة، فالطرفان يحتاجان انتباهًا.</p>\n<p>صدّر بضبط جودة عالية وراجع النتيجة بالحجم الكامل: اقترب من المناطق الفاتحة والداكنة وتأكد من عدم فقدان تفاصيل.</p>\n<h2 id=\"contrast-for-black-white\">التباين لصور بالأبيض والأسود</h2>\n<p>صور الأبيض والأسود تعيش أو تموت بالتباين: بلا لون يدعم الصورة، النطاق النغمي هو كل شيء، وصورة مسطحة بالأبيض والأسود تبدو رمادية وبلا حياة.</p>\n<p>استخدم دفعة تباين أقوى للأبيض والأسود مما للون: دفعة 20 إلى 30 بالمئة تعطي الصورة سودًا عميقة وبيضًا ساطعة تجعلها لافتة. وراقب النغمات الوسطى أثناء زيادة التباين: صورة شخصية بالأبيض والأسود تحتاج رماديًا ناعمًا في البشرة، وتباين كثير جدًا يحوّل الوجه إلى بقع قاسية من الأبيض والأسود.</p>\n<p>ولمنظر بالأبيض والأسود، التباين هو أداتك الرئيسية: الجبال والسماء والمقدمة تكسب تعريفًا باتساع نغمي واضح.</p>\n<p>للعملية خطوة بخطوة، راجع <a href=\"/ar/blog/kayfiyya-taadil-tabayun-as-sura/\">كيف تضبط تباين صورة</a>. وللمقارنة، اقرأ <a href=\"/ar/blog/sutoo-vs-taarid-vs-tabayun/\">السطوع أم التعريض أم التباين: أساسيات التعديل</a>، ولإصلاح صورة داكنة أولًا استخدم <a href=\"/ar/taadil-sutoo-as-sura/\">محرر سطوع الصور</a>. وجرّب كل ضبط مجانًا في <a href=\"/ar/taadil-tabayun-as-sura/\">محرر تباين الصور</a>.</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"كم تباينًا يجب أن أضيف إلى صورة مسطحة؟","answer":"ابدأ بـ10 إلى 20 بالمئة وراجع المعاينة: معظم الصور المسطحة تحتاج دفعة صغيرة فقط، والحركات الأكبر تقص الإضاءات وتسحق الظلال بسرعة. وزد بخطوات صغيرة وتوقف عندما تبدو الصورة قوية دون أن تفقد تفاصيل."},{"question":"لماذا تبدو صورتي قاسية بعد إضافة تباين؟","answer":"دُفع التباين أكثر مما يلزم، ما يعمّق الظلال ويفتّح الإضاءات أبعد من النقطة التي ينجو فيها التفصيل: اخفض المنزلق حتى تُظهر البشرة والسماء ومناطق الظل ملمسًا مجددًا."},{"question":"هل يمكن للتباين إصلاح صورة داكنة جدًا؟","answer":"لا، التباين يغيّر الاتساع لا المستوى، فصورة داكنة بتباين عالٍ تبقى داكنة، فقط بظلال أعمق: فتّح الصورة أولًا بمحرر السطوع، ثم أضف تباينًا إذا بدت مسطحة."},{"question":"هل أستخدم تباينًا موجبًا أم سالبًا لصورة شخصية؟","answer":"عادة دفعة موجبة صغيرة 5 إلى 10 بالمئة، تحدد الوجه دون قسوة: ولصورة شخصية ملتقطة بشمس ظهيرة قاسية، تباين سالب 10 إلى 20 بالمئة سالبة يلطّف الظلال ويجعل البشرة أنعم."},{"question":"هل زيادة التباين تجعل الألوان أقوى أيضًا؟","answer":"نعم، رفع التباين يجعل الألوان أغنى، لأن الداكن يصبح أظلم والفاتح أفتح حوله: وإذا أصبحت الألوان قوية جدًا، اخفض التشبع قليلًا بعدها بمحرر التشبع."},{"question":"هل تعديل تباين صورة شخصية في أداة متصفح آمن؟","answer":"نعم، لأن كل المعالجة تحدث محليًا في متصفحك ولا يُرفع شيء إلى خادم: وتزيل الأداة أيضًا بيانات GPS EXIF عند التصدير. واحتفظ بالملف الأصلي إذا أردت تجربة مستوى تباين آخر."}];
